import assert from 'node:assert/strict';
import '../../midi.js';
const M=globalThis.EK1MIDI;
const track=events=>[77,84,114,107,0,0,(events.length>>8)&255,events.length&255,...events];
const file=(...tracks)=>Uint8Array.from([77,84,104,100,0,0,0,6,0,tracks.length>1?1:0,0,tracks.length,1,224,...tracks.flatMap(track)]);
const end=[0,255,47,0];
const tempo=[0,255,81,3,7,161,32,0x83,0x60,255,81,3,15,66,64,...end];
const piano=[0,0xc0,4,0,0x90,60,100,0,0xb0,64,127,0x83,0x60,0x80,60,0,0x83,0x60,0xb0,64,0,...end];
const bass=[0,0xc1,33,0,0x91,36,80,0,40,70,0x83,0x60,36,0,0,40,0,...end];
const percussion=[0,0x99,36,90,0x78,0x89,36,0,...end];
const imported=M.parse(file(tempo,piano,bass,percussion));
assert.equal(imported.format,1);
assert.deepEqual(imported.channels,[0,1,9]);
assert.equal(imported.notes.length,4);
assert.equal(imported.notes.find(n=>n.key===60).duration,1.5);
assert.equal(imported.notes.find(n=>n.key===36&&n.channel===1).duration,.5);
assert.equal(imported.notes.find(n=>n.channel===9).duration,.125);
assert.equal(imported.notes.find(n=>n.key===40).program,33);
assert.equal(M.drumFor(36),'kick');
assert.equal(M.toneFor(33),10);
const take=[{midi:60,t:0,length:.5,tone:0},{midi:64,t:.25,length:.75,tone:10},{midi:72,t:1,length:.125,tone:9}];
const roundtrip=M.parse(M.encodeTake(take));
assert.deepEqual(roundtrip.notes.map(n=>[n.key,n.time,n.duration,n.program]),[[60,0,.5,0],[64,.25,.75,33],[72,1,.125,89]]);
assert(!roundtrip.channels.includes(9));
for(const bad of [new Uint8Array([1,2,3]),file([0,0x90,60,80]),file([0,0x90,60,255,...end]),file(end),file([0x81,0x81,0x81,0x81,0,...end])])assert.throws(()=>M.parse(bad));
assert.throws(()=>M.encodeTake([]));
console.log('PASS MIDI format 0/1, tempo changes, running status, sustain, drums, roundtrip and malformed input');
